"""Interaction-model widgets — recognise gestures on an arbitrary child, instead
of being limited to a Button's click or a Draggable's drag.

``GestureDetector`` wraps any widget and fires a handler on tap, double-tap,
long-press, or a directional swipe. ``Dismissible`` is the swipe-to-dismiss row
(delete-by-swiping a list item), calling ``on_dismissed(direction)`` once the
swipe passes a threshold. Both are pointer-based, so they work for mouse and
touch alike, and stay inside the no-injection rule (handlers are the developer's
own method references / lambdas, never user input).
"""
from __future__ import annotations

from typing import Any, Callable

from workpeg.ui.state import Binding
from workpeg.ui.widgets.base import BaseWidget, WidgetChild


class GestureDetector(BaseWidget):
    """Recognise pointer gestures on a single ``child`` and fire a handler.

    Unlike ``Button``/``Link`` (click only), this works on *any* widget — wrap a
    ``Text``, ``Image``, ``Container`` or a whole subtree — and adds touch-style
    gestures::

        GestureDetector(
            Card(item),
            on_tap=self.open,
            on_long_press=self.show_menu,
            on_swipe_left=self.archive,
        )

    Every handler is a ``self.method`` reference or a lambda. ``on_tap`` is a
    quick press-and-release; ``on_double_tap`` two taps in quick succession (when
    set, a lone tap is held briefly to disambiguate); ``on_long_press`` a press
    held in place; ``on_swipe_*`` a drag past a small threshold in that
    direction. At least one handler is required.
    """

    widget_type = "GestureDetector"

    def __init__(
        self,
        child: WidgetChild,
        *,
        on_tap: Callable | None = None,
        on_double_tap: Callable | None = None,
        on_long_press: Callable | None = None,
        on_swipe_left: Callable | None = None,
        on_swipe_right: Callable | None = None,
        on_swipe_up: Callable | None = None,
        on_swipe_down: Callable | None = None,
        key: str | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.child = child
        self.on_tap = on_tap
        self.on_double_tap = on_double_tap
        self.on_long_press = on_long_press
        self.on_swipe_left = on_swipe_left
        self.on_swipe_right = on_swipe_right
        self.on_swipe_up = on_swipe_up
        self.on_swipe_down = on_swipe_down


class Dismissible(BaseWidget):
    """Swipe a ``child`` away — the delete-by-swiping list row. Dragging past
    ``threshold`` (a fraction of the row's size) slides it off-screen and calls
    ``on_dismissed(direction)``; release short of it snaps back::

        Dismissible(
            ListTile(title=task.name),
            key=f"task-{task.id}",
            direction="left",                       # only a left swipe dismisses
            background=Container(Text("Delete"), color="#e23b3b"),
            on_dismissed=self.remove_task,          # def remove_task(self, direction)
        )

    ``on_dismissed`` should remove the item from state (the widget only animates
    it out — like Flutter, the row reappears if you don't). ``direction`` limits
    which swipes count: ``"horizontal"`` (default) · ``"vertical"`` · ``"left"``
    · ``"right"`` · ``"up"`` · ``"down"``. ``background`` is an optional widget
    revealed behind the row as it slides. ``key`` is required (the row's
    identity).
    """

    widget_type = "Dismissible"

    def __init__(
        self,
        child: WidgetChild,
        *,
        key: str | Binding,
        on_dismissed: Callable,
        direction: str = "horizontal",
        threshold: float = 0.4,
        background: WidgetChild | None = None,
        **kwargs: Any,
    ):
        super().__init__(key=key, **kwargs)
        self.child = child
        self.on_dismissed = on_dismissed
        self.direction = direction
        self.threshold = threshold
        self.background = background
